import random
from datetime import date, timedelta
from string import ascii_uppercase
from .synth import *

# %% ../nbs/01_coffee.ipynb #023e75df
DIMS = dict(problem=['water stress', 'equipment fault', 'both'],
            pattern=['one node', 'cluster', 'widespread'],
            severity=['early', 'moderate', 'severe'])
SEVERITIES = DIMS['severity']

# %% ../nbs/01_coffee.ipynb #148459bf
def layout(rng:random.Random)->list[tuple]:
    "A random farm: (group name, node locations) pairs, in one of three naming schemes"
    scheme = rng.choice(['benches', 'blocks', 'plots'])
    if scheme == 'benches':
        return [(f'Bench {b}', [f'Bench {b}, plant {p}' for p in range(1, rng.randint(2, 4)+1)])
                for b in range(1, rng.randint(2, 4)+1)]
    groups = []
    for g in range(rng.randint(3, 8)):
        rows = sorted(rng.sample(range(1, 30), rng.randint(4, 10)))
        if scheme == 'blocks':
            L = ascii_uppercase[g]
            groups.append((f'Block {L}, drip line {L}{rng.randint(1, 4)}', [f'Block {L}, row {r}' for r in rows]))
        else: groups.append((f'Plot {g+1}', [f'Plot {g+1}, row {r}' for r in rows]))
    return groups

# %% ../nbs/01_coffee.ipynb #5f88f4db
FAULTS = ['missing data', 'implausible values', 'camera view changed']
SENSORS = ['soil moisture', 'thermal camera', 'air temperature', 'humidity']

# %% ../nbs/01_coffee.ipynb #78af7dbf
ONSET = {('water stress', 'early'): (0, 1), ('water stress', 'moderate'): (2, 4), ('water stress', 'severe'): (4, 8),
         ('equipment fault', 'early'): (0, 1), ('equipment fault', 'moderate'): (1, 3), ('equipment fault', 'severe'): (4, 10)}

# %% ../nbs/01_coffee.ipynb #16ddec72
WEEKDAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']

def _since(day, days):
    "When a problem started, `days` before `day`, as a phrase for the message"
    if days == 0: return 'since today'
    if days == 1: return 'since yesterday'
    if days < 7: return f'since {WEEKDAYS[(day - timedelta(days)).weekday()]}'
    return 'for a week or more'

# %% ../nbs/01_coffee.ipynb #a36c737e
def amount(
    flagged:int, # Flagged nodes in the group
    total:int, # Nodes in the group
)->str:
    "The amount word for `flagged` nodes out of `total`"
    r = flagged / total
    return 'all' if r == 1 else 'almost all' if r >= 0.8 else 'most' if r > 0.5 else 'some'

# %% ../nbs/01_coffee.ipynb #f63bc3e2
def _free(groups, used): return [(g, ns) for g, ns in groups if g not in used and not used & set(ns)]
def _wide(n): return int(0.7*n)+1  # fewest flagged nodes that make an item widespread, on a farm of `n` nodes
def _flagged(items, kind): return sum(it.get('nodes_flagged', 1) for it in items if it['problem'] == kind and it['pattern'] != 'widespread')

def _cause(rng, problem, pattern, severity, day, days):
    "The observed cause fields of an item that started `days` before `day`"
    if problem == 'water stress':
        return dict(soil_water='arriving' if rng.random() < 0.3 else f"none {_since(day, days + rng.randint(0, 2))}")
    if severity != 'early' or pattern != 'one node': return dict(fault='missing data')
    fault = rng.choice(FAULTS)
    return dict(fault=fault, sensor=rng.choice(SENSORS)) if fault == 'implausible values' else dict(fault=fault)

def _counts(f, n): return dict(nodes_flagged=f, nodes_in_group=n, amount=amount(f, n))

def _item(rng, problem, pattern, severity, groups, used, day):
    "One triage item; adds its location to `used`"
    if pattern == 'widespread':
        n = sum(len(ns) for _, ns in groups)
        loc, counts = 'whole farm', _counts(rng.randint(_wide(n), n), n)
    else:
        g, ns = rng.choice(_free(groups, used))
        if pattern == 'one node': loc, counts = rng.choice(ns), {}
        else: loc, counts = g, _counts(rng.randint(min(2, len(ns)), len(ns)), len(ns))
        used.add(loc)
    lo, hi = ONSET[problem, severity]
    days = rng.randint(lo, hi)
    return dict(problem=problem, location=loc, pattern=pattern, severity=severity,
                since=_since(day, days), **_cause(rng, problem, pattern, severity, day, days), **counts)

# %% ../nbs/01_coffee.ipynb #c8286935
FARMS = ['Fazenda Boa Vista', 'Sítio Santa Luzia', 'Fazenda Cachoeira', 'Sítio Bela Vista', 'Fazenda São João', 'Sítio Recanto']
KINDS = ['water stress', 'equipment fault']

# %% ../nbs/01_coffee.ipynb #a046ef68
def triage(t:dict, # Tuple: `problem`, `pattern` and `severity` of the main item
           rng:random.Random
          )->dict:
    "A random triage record for one farm and one day, whose main item matches `t`"
    groups, used = layout(rng), set()
    n = sum(len(ns) for _, ns in groups)
    day = date(2026, 5, 1) + timedelta(rng.randint(0, 152))
    both = t['problem'] == 'both'
    if not both: main = t['problem']
    elif t['pattern'] == 'widespread' and t['severity'] != 'early': main = 'water stress'
    else: main = rng.choice(KINDS)
    items = [_item(rng, main, t['pattern'], t['severity'], groups, used, day)]
    for i in range(rng.choice([1, 1, 2] if both else [0, 0, 1, 1, 2])):
        kind = KINDS[1 - KINDS.index(main)] if both and i == 0 else rng.choice(KINDS) if both else main
        if t['pattern'] == 'widespread' and kind == main: continue  # the main item already covers the farm
        if not _free(groups, used): break
        sev = rng.choice(SEVERITIES[:SEVERITIES.index(t['severity'])+1])
        it = _item(rng, kind, rng.choice(['one node', 'cluster']), sev, groups, used, day)
        if _flagged(items + [it], kind) >= _wide(n): break
        items.append(it)
    items.sort(key=lambda it: SEVERITIES.index(it['severity']), reverse=True)
    return dict(farm=rng.choice(FARMS), date=str(day), nodes=n, items=items)
